'use strict';
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={lang:0,business:'ac',done:[],answers:{},checks:[],drafts:{},keywordScores:{},diagnosed:[],missions:{},maths:{},businessChecks:{},guideChecks:{},casePlans:{},journey:{},clinic:{traces:[],answers:{},notes:{},consent:cleanConsent()},optimization:{},studio:{},destination:{}};
let state;try{const saved=JSON.parse(localStorage.getItem('ads-asaan-v1')||'null');state={...structuredClone(initial),...saved};if(!Array.isArray(state.done)||![0,1].includes(state.lang))state=structuredClone(initial);}catch{state=structuredClone(initial);}
let storageOK=true;
state.missions=cleanMissions(state.missions);state.maths=cleanMaths(state.maths);migrateBusinessChecks();state.casePlans=cleanCasePlans(state.casePlans);state.journey=cleanJourney(state.journey);state.clinic=cleanClinic(state.clinic);state.optimization=cleanOptimization(state.optimization);state.studio=cleanStudio(state.studio);state.destination=cleanDestination(state.destination);
function save(){try{localStorage.setItem('ads-asaan-v1',JSON.stringify(state));}catch{storageOK=false;}}
const t=x=>Array.isArray(x)?x[state.lang]:x;
const U=(a,b)=>state.lang?b:a;
const biz=()=>BUSINESSES.find(b=>b.id===state.business)||BUSINESSES[0];
const money=x=>Number.isFinite(x)?'Rs '+Math.round(x).toLocaleString('en-PK'):'—';
const num=(x,n=1)=>Number.isFinite(x)?x.toLocaleString('en-PK',{maximumFractionDigits:n}):'—';
function icon(name,size=20){const shapes={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',book:'<path d="M4 4h6a3 3 0 0 1 2 1 3 3 0 0 1 2-1h6v15h-6a3 3 0 0 0-2 1 3 3 0 0 0-2-1H4Z"/><path d="M12 5v15"/>',flask:'<path d="M9 3h6m-5 0v7L4 20h16l-6-10V3M7 15h10"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h1m3 0h1m3 0h1M8 15h1m3 0h1m3 0h1M8 19h1m3 0h5"/>',play:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4Z"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',layers:'<path d="m3 7 9-5 9 5-9 5ZM3 12l9 5 9-5M3 17l9 5 9-5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4m-2-2h4"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',edit:'<path d="m15 4 5 5M4 15 16 3l5 5L9 20l-6 1Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 7V4l14-2v3m4 6h-6v5h6"/>',rocket:'<path d="M8 16c0-8 4-12 12-12 0 8-4 12-12 12Zm0-6-4 1-2 5h6m6 0v5l5-2 1-6M6 18l-3 3"/>',tool:'<path d="M20 3a6 6 0 0 1-7 8L5 21l-3-3 10-8a6 6 0 0 1 8-7l-4 4 2 2Z"/>',flag:'<path d="M5 22V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.book}</svg>`;}
const NAV=[['home','home',P('Overview','Overview')],['learn','book',P('Learning path','Learning path')],['destination','target',P('Landing page lab','Landing page lab')],['studio','edit',P('Ads & keywords','Ads & keywords')],['optimize','chart',P('Optimize & scale','Optimize & scale')],['clinic','activity',P('Tracking & diagnosis','Tracking & diagnosis')],['journey','rocket',P('Start-to-finish setup','Start-to-finish setup')],['guides','compass',P('Setup workbooks','Setup workbooks')],['workshop','layers',P('Guided practice','Guided practice')],['lab','flask',P('Practice lab','Practice lab')],['calculators','calculator',P('Calculators','Calculators')],['screens','target',P('Real screenshots','Real screenshots')],['media','play',P('Visual library','Visual library')],['reference','search',P('Quick reference','Quick reference')],['progress','chart',P('My progress','My progress')]];
function route(){const [page='home',id='0']=location.hash.slice(1).split('/');return{page:page||'home',id:Number(id)||0};}
function go(page){location.hash=page;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function nextLesson(){return LESSONS.find(l=>!state.done.includes(l.id))||LESSONS[0];}
function render(){const r=route();const active=r.page==='lesson'?'learn':r.page==='case'?'workshop':r.page==='consent'?'clinic':r.page;document.documentElement.lang=state.lang?'en':'ur-Latn';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="logo" href="#home" aria-label="Ads Asaan home"><span class="logo-mark">a<span style="display:none">a</span></span><span>ads <b>asaan</b><span style="color:#718958">.</span></span></a><div class="label">YOUR LEARNING SPACE</div><nav class="nav">${NAV.map(([p,i,n])=>`<button class="nav-btn ${active===p?'active':''}" data-go="${p}" ${active===p?'aria-current="page"':''}>${icon(i)}${t(n)}${p==='lab'?'<em>TRY IT</em>':''}</button>`).join('')}</nav><div class="side-note"><div class="label" style="margin:0">SMALL STEPS. REAL SKILLS.</div><p>${U('Har lesson ke baad khud try karo. Galti se hi learning hoti hai.','Try it after every lesson. Mistakes are part of learning.')}</p><div class="progress-track"><div class="progress-fill" style="width:${state.done.length/LESSONS.length*100}%"></div></div><p style="margin-bottom:0">${state.done.length} / ${LESSONS.length} ${U('lessons complete','lessons completed')}</p></div><div class="side-bottom"><span class="avatar">Y</span><span>${U('Apni pace par seekho','Learn at your own pace')}<br><small style="color:var(--muted)">Search Ads · v0.12</small></span></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Google Ads Academy <span style="padding:0 9px">/</span><b>${r.page==='lesson'?U('Search Ads ka lesson','Search Ads lesson'):t(NAV.find(n=>n[0]===r.page)?.[2]||P(r.page==='case'?'Worked campaign case':'Search Ads',r.page==='case'?'Worked campaign case':'Search Ads'))}</b></div><div class="controls"><span class="saved"><i class="dot"></i>${storageOK?U('Progress is browser mein saved','Progress saved in this browser'):U('Storage available nahi','Storage unavailable')}</span><select id="language" class="lang" aria-label="Learning language"><option value="0" ${state.lang===0?'selected':''}>Roman Urdu</option><option value="1" ${state.lang===1?'selected':''}>English</option></select><span class="avatar">Y</span></div></header><div class="page" id="page">${({home:home,learn:learn,lesson:()=>lessonPage(r.id),lab:labPage,case:casePage,destination:destinationPage,studio:studioPage,optimize:optimizePage,consent:consentPage,clinic:clinicPage,journey:journeyPage,guides:guidesPage,workshop:workshopPage,calculators:calculatorPage,screens:screensPage,media:mediaPage,reference:referencePage,progress:progressPage}[r.page]||home)()}</div></main></div>`;bind();if(r.page==='calculators')calcResults();if(r.page==='lab'){bindLab();bindDraftAutosave();}if(r.page==='guides')bindGuides();if(r.page==='journey')bindJourney();if(r.page==='clinic')bindClinic();if(r.page==='consent')bindConsent();if(r.page==='optimize')bindOptimize();if(r.page==='studio')bindStudio();if(r.page==='destination')bindDestination();if(r.page==='case')bindStandaloneCase();if(r.page==='lesson')bindMedia();if(r.page==='workshop')bindWorkshop();if(r.page==='reference')bindReference();if(r.page==='media')bindMedia();if(r.page==='screens')bindScreens();window.scrollTo(0,0);}
function heading(eyebrow,title,sub,tag=''){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${tag?`<span class="tag"><i class="dot"></i>${tag}</span>`:''}</div>`;}
function home(){const n=nextLesson(),b=biz();return `${heading('LESS THEORY. MORE DOING.',U('Google Ads, ab asaan.','Google Ads, made simple.'),U('Chhote lessons. Real examples. Khud karke seekho.','Small lessons. Real examples. Learn by doing.'),'SEARCH ADS · FIRST EDITION')}<section class="hero"><div><div class="eyebrow">YOUR FIRST CHAPTER STARTS HERE</div><h2>${U('Search se shuru karo.<br><span>Skills khud banao.</span>','Start with Search.<br><span>Build skills by doing.</span>')}</h2><p>${U('Keywords se conversions tak. Har step ko samjho, try karo aur apne business par apply karo.','From keywords to conversions. Understand each step, try it and apply it to your business.')}</p><button class="btn lime" data-go="lesson/${n.id}">${state.done.length?U('Learning continue karo','Continue learning'):U('Pehla lesson shuru karo','Start your first lesson')} ${icon('arrow',16)}</button><div class="mini">${icon('clock',13)} ${U('Apni pace par · Roman Urdu + English','At your own pace · Roman Urdu + English')}</div></div><div class="search-illustration"><div class="search-card"><div class="searchbox"><span class="g">G</span><span>${esc(b.customer[state.lang])}</span><span style="margin-left:auto">${icon('search',13)}</span></div><div class="serp"><div class="sponsored">Sponsored · ${esc(b.name[1])}</div><div class="url">${esc(b.domain)} › services</div><h3>${esc(b.offer[1])} | ${esc(b.benefit[1])}</h3><p>${esc(b.desc[1])}</p></div><div class="floating-badge">${icon('check',13)} ${U('Sahi search. Relevant ad.','Right search. Relevant ad.')}</div></div><small style="position:absolute;bottom:-5px;color:#adbfac;font-size:9px">${U('Illustration · Google ka screenshot nahi','Illustration · not a Google screenshot')}</small></div></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('book',21)}</span><div><strong>${LESSONS.length}</strong><p>${U('Chhote practical lessons','Bite-size practical lessons')}</p></div></div><div class="stat"><span class="stat-icon">${icon('flask',21)}</span><div><strong>4</strong><p>${U('Interactive practice labs','Interactive practice labs')}</p></div></div><div class="stat"><span class="stat-icon">${icon('target',21)}</span><div><strong>3</strong><p>${U('Businesses, real context','Businesses, real context')}</p></div></div></div><section class="workshop-banner"><div><div class="eyebrow">NEW · FULL RSA & KEYWORD WORKSHOP</div><h3>${U("Ad ke combinations aur negatives try karo.","Try ad combinations and negative keywords.")}</h3><p>${U("15 headlines, 4 descriptions, pins aur useful-query conflicts.","15 headlines, four descriptions, pins and useful-query conflicts.")}</p></div><button class="btn" data-go="studio">${U("Studio kholo","Open studio")} →</button></section><section class="workshop-banner"><div><div class="eyebrow">NEW · OPTIMIZE & SCALE</div><h3>${U("Extra budget ka result samjho.","Understand the next budget increase.")}</h3><p>${U("6 evidence decisions, scaling model aur apna experiment plan.","Six evidence decisions, a scaling model and your experiment plan.")}</p></div><button class="btn" data-go="optimize">${U("Optimization try karo","Try optimization")} →</button></section><section class="workshop-banner"><div><div class="eyebrow">NEW · TRACKING & TROUBLESHOOTING</div><h3>${U("Numbers sahi hain? Problem kahan hai?","Are the numbers right? Where is the problem?")}</h3><p>${U("3 event experiments aur 8 evidence-based fault cases.","Three event experiments and eight evidence-based fault cases.")}</p></div><button class="btn" data-go="clinic">${U("Diagnosis try karo","Try diagnosis")} →</button></section><section class="workshop-banner"><div><div class="eyebrow">NEW · START TO FIRST REVIEW</div><h3>${U("Apna Search campaign plan banao.","Build your Search campaign plan.")}</h3><p>${U("14 connected steps, decisions, calculations aur tumhara exportable plan.","14 connected steps, decisions, calculations and your exportable plan.")}</p></div><button class="btn" data-go="journey">${U("Setup shuru karo","Start setup")} →</button></section><section class="workshop-banner"><div><div class="eyebrow">NEW · ORIGINAL GOOGLE ADS UI</div><h3>${U("Real screen par seekho.","Learn on the real screen.")}</h3><p>${U("9 original screenshots · clickable Roman Urdu + English explanations.","Nine original screenshots · clickable Roman Urdu + English explanations.")}</p></div><button class="btn" data-go="screens">${U("Screens dekho","Explore screens")} →</button></section><section class="workshop-banner"><div><div class="eyebrow">NEW · SETUP WORKBOOKS</div><h3>${U('Ab apna setup plan banao.','Now build your setup plan.')}</h3><p>${U('23 implementation steps aur 7 official Google videos.','23 implementation steps and 7 official Google videos.')}</p></div><button class="btn" data-go="guides">${U('Workbook kholo','Open a workbook')} →</button></section><div class="cols"><section><div class="section-heading"><h2>${U('Tumhara learning path','Your learning path')}</h2><button class="text-btn" data-go="learn">${U('Sab lessons dekho','View all lessons')} ↗</button></div>${CHAPTERS.slice(0,4).map((c,i)=>chapterCard(c,i)).join('')}<button class="text-btn" data-go="learn">${U('Aur 10 chapters explore karo','Explore 10 more chapters')} ${icon('arrow',15)}</button></section><aside class="rail"><div class="rail-card"><h3>${U('Apna example choose karo','Choose your example')}</h3><p>${U('Ek hi concept, alag business context.','The same concept, a different business context.')}</p>${businessPicker()}</div><div class="rail-card tip-card"><div class="label">${icon('spark',14)} A LITTLE AHA MOMENT</div><p>${U('Har click customer nahi hota. Pehle samjho banda kya dhoond raha hai.','Every click is not a customer. First understand what the person is looking for.')}</p><button class="text-btn" data-go="lab">${U('Search intent try karo','Try search intent')} →</button></div></aside></div>${footer()}`;}
function chapterCard(c,i){const ls=LESSONS.filter(l=>l.c===i),done=ls.filter(l=>state.done.includes(l.id)).length,target=ls.find(l=>!state.done.includes(l.id))||ls[0];return `<article class="chapter ${nextLesson().c===i?'current':''}"><span class="chapter-num">${done===ls.length?icon('check',19):String(i+1).padStart(2,'0')}</span><div class="chapter-content"><h3><button data-go="lesson/${target.id}" style="padding:0;text-align:left">${esc(c[state.lang?0:1])}</button></h3><p>${esc(c[state.lang?2:3])}</p><div class="chapter-meta"><span>${ls.length} lessons</span><span>·</span><span>${ls.reduce((s,l)=>s+l.minutes,0)} min ${U('estimate','estimate')}</span>${i===0&&!done?'<span class="pill">START HERE</span>':''}${done?`<span class="pill">${done}/${ls.length} complete</span>`:''}</div></div><button class="chapter-arrow" data-go="lesson/${target.id}" aria-label="${esc(t(target.title))}">${icon('arrow',18)}</button></article>`;}
function businessPicker(){return `<div class="business-list">${BUSINESSES.map(b=>`<button class="business-btn ${b.id===state.business?'active':''}" data-business="${b.id}" aria-pressed="${b.id===state.business}"><span class="business-emoji">${b.emoji}</span><span>${esc(t(b.name))}<small>${esc(t(b.type))}</small></span>${b.id===state.business?`<span class="check">${icon('check',14)}</span>`:''}</button>`).join('')}</div>`;}
function footer(){return `<div class="footer-note"><span>Ads Asaan · ${U('Independent learning app. Google se affiliated nahi.','Independent learning app. Not affiliated with Google.')}</span><span>${U('Source review','Source review')}: 20 Oct 2026 · <a href="#reference">${U('Sources aur coverage','Sources & coverage')}</a></span></div>`;}
function learn(){return `${heading('YOUR ROADMAP',U('Step by step. Sab connected.','Step by step. All connected.'),U('42 introductory lessons aur practice. Deep implementation guides sources mein linked hain.','42 introductory lessons and practice. Detailed implementation guides are linked in sources.'))}<div class="note" style="margin-bottom:22px">${U('v0.9: Learning path accessible hai. Original account-specific screenshots aur Roman Urdu video recordings abhi complete nahi. Visual library mein Google ke official media aur links hain.','v0.9: The learning path is available. Nine original interface crops are available. Full workflow screenshots and Roman Urdu recordings remain. The visual library contains official Google media and links.')}</div><div class="cols"><section>${CHAPTERS.map(chapterCard).join('')}</section><aside class="rail"><div class="rail-card"><h3>${U('Practice tumhari marzi se','Practice your way')}</h3><p>${U('Lessons locked nahi. Jahan zarurat ho, wahan jump karo.','No locked lessons. Jump to what you need.')}</p>${businessPicker()}</div><div class="rail-card"><h3>${U('Sirf parhna nahi','Go beyond reading')}</h3><p>${U('Har lesson ki activity karo, quiz solve karo, phir complete mark karo.','Try the activity, solve the quiz, then mark the lesson complete.')}</p><button class="btn light" data-go="lab">${U('Practice lab kholo','Open practice lab')}</button></div></aside></div>${footer()}`;}
function sourceLinks(keys){return keys.map(k=>`<a class="source-link" href="https://support.google.com/google-ads/answer/${SOURCES[k][1]}?hl=en" target="_blank" rel="noopener noreferrer">↗ ${esc(SOURCES[k][0])}</a>`).join('');}
function typesGallery(){return `<section id="types-gallery" class="lesson-section"><h3>${U('Campaign types ki mini gallery','A mini campaign-type gallery')}</h3><p>${U('Har type khol kar ek simple example dekho.','Open a type to see a simple example.')}</p>${[
['Search',P('Google par service/product dhoondtay waqt relevant search ad.','Relevant search ads when someone looks for a service or product.'),'AC repair Lahore → CoolCare repair ad'],
['Display',P('Websites aur apps par visual ads.','Visual ads across websites and apps.'),'News website → shoe store banner'],
['Shopping',P('Product photo, price aur store ki listing.','Product listings with an image, price and store.'),'Running shoes → product image + price'],
['Video',P('YouTube aur eligible video partner placements par video advertising.','Video advertising on YouTube and eligible video partner placements.'),'YouTube → brand video'],
['App',P('App installs ya engagement barhanay ki campaigns.','Campaigns for app installs or engagement.'),'Fitness app → install / use app'],
['Demand Gen',P('Visual placements se interest aur demand paida karna.','Building interest and demand through visual placements.'),'New shoe collection → visual discovery'],
['Performance Max',P('Ek campaign se multiple Google channels par goal-based delivery.','Goal-based delivery across multiple Google channels through one campaign.'),'Store sales goal → Search + Shopping + other eligible channels']
].map(([name,desc,ex],i)=>`<details class="type-detail" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span> ${name}<b>+</b></summary><p>${esc(t(desc))}</p><div class="formula">${esc(ex)}</div><small class="simulation-label">CONCEPT EXAMPLE · NOT A SCREENSHOT</small></details>`).join('')}</section>`;}
function lessonPage(id){const l=LESSONS[id]||LESSONS[0],ls=LESSONS.filter(x=>x.c===l.c),a=state.answers[l.id];return `<button class="text-btn" data-go="learn" style="margin-bottom:20px">← ${U('Learning path','Learning path')}</button><div class="lesson-layout"><article><div class="lesson-head"><div class="eyebrow">CHAPTER ${l.c+1} · LESSON ${ls.indexOf(l)+1} OF ${ls.length}</div><h1>${esc(t(l.title))}</h1><div class="badge-row"><span class="tag">${icon('clock',12)} ${l.minutes} min estimate</span><span class="tag">${esc(t(biz().name))}</span>${state.done.includes(l.id)?'<span class="tag">✓ Completed</span>':''}</div></div><div class="lesson-section"><h3>${U('Seedhi si baat','The simple idea')}</h3><p>${esc(t(l.why))}</p></div><div class="example"><div class="label">${U('EK ASAAN EXAMPLE','A SIMPLE EXAMPLE')}</div><p>${esc(t(l.example))}</p></div>${l.id===0?typesGallery():''}<div class="lesson-section"><h3>${U('Ab khud karo','Now try it yourself')}</h3><ol class="steps">${l.steps.map(s=>`<li>${esc(t(s))}</li>`).join('')}</ol>${l.lab?`<button class="btn light" data-lab="${l.lab}">${icon('flask',16)} ${U('Related activity kholo','Open related activity')}</button>`:''}</div>${workshopLessonLink(l.c)}${lessonVideoLink(l)}<section class="quiz" aria-label="Lesson check"><div class="eyebrow">QUICK CHECK</div><h3>${esc(t(l.q))}</h3><div class="quiz-options">${l.options.map((o,i)=>`<button class="option ${a===i?(i===l.answer?'correct':'wrong'):''}" data-answer="${i}" data-lesson="${l.id}">${String.fromCharCode(65+i)}. ${esc(t(o))}</button>`).join('')}</div>${a!==undefined?`<div class="feedback ${a===l.answer?'':'error'}" role="status"><b>${a===l.answer?U('Sahi samjhay!','You got it!'):U('Dobara socho.','Try again.')}</b> ${esc(t(l.feedback))}</div>`:''}<div class="action-row"><button class="btn" id="complete-lesson" data-id="${l.id}" ${a!==l.answer?'disabled style="opacity:.45;cursor:not-allowed"':''}>${icon('check',16)} ${state.done.includes(l.id)?U('Complete hai — continue','Completed — continue'):U('Lesson complete karo','Complete lesson')}</button></div></section><div class="lesson-nav">${l.id?`<button class="btn light" data-go="lesson/${l.id-1}">← ${U('Pichla lesson','Previous lesson')}</button>`:'<span></span>'}${l.id<LESSONS.length-1?`<button class="btn light" data-go="lesson/${l.id+1}">${U('Agla lesson','Next lesson')} →</button>`:`<button class="btn light" data-go="progress">${U('Progress dekho','View progress')} →</button>`}</div></article><aside class="lesson-aside"><div class="rail-card"><div class="label" style="margin-bottom:12px">IN THIS CHAPTER</div>${ls.map(x=>`<button class="lesson-link ${x.id===l.id?'active':''}" data-go="lesson/${x.id}">${state.done.includes(x.id)?'✓':'○'} ${esc(t(x.title))}</button>`).join('')}</div><div class="rail-card"><h3>${U('Official sources','Official sources')}</h3>${l.sources.length?sourceLinks(l.sources):`<p>${U('Original worked example. Assumptions ko apne business ke data se replace karo.','Original worked example. Replace assumptions with your own business data.')}</p>`}<small style="color:var(--muted)">${U('Review','Reviewed')}: 20 Oct 2026</small></div><div class="note">${U('Lesson ek simple introduction hai. Implementation ke liye linked official guide aur account ke current options verify karo.','This lesson is a simple introduction. For implementation, verify the linked official guide and current account options.')}</div></aside></div>${footer()}`;}
let labTab='keywords',calcTab='forecast';
function labPage(){return `<div class="action-row" style="margin-bottom:20px"><button class="btn light" data-go="studio">${U("Full RSA aur keyword workshop kholo","Open the full RSA and keyword workshop")} →</button></div>${heading('SAFE SPACE TO MAKE MISTAKES',U('Try karo. Samjho. Dobara karo.','Try it. Understand it. Try again.'),U('Ye practice simulator hai. Koi real ad ya spend create nahi hota.','This is a practice simulator. It creates no real ads or spending.'))}<div class="section-heading"><span class="tag">${esc(t(biz().name))} · ${esc(t(biz().type))}</span><select id="business-select" class="lang" aria-label="Example business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs">${[['keywords',P('Search-term lab','Search-term lab')],['ad',P('Ad likho','Ad builder')],['campaign',P('Campaign banao','Campaign builder')],['diagnose',P('Problem solve karo','Diagnosis lab')]].map(([k,n])=>`<button data-labtab="${k}" class="${k===labTab?'active':''}">${t(n)}</button>`).join('')}</div><div id="lab-content">${({keywords:keywordLab,ad:adLab,campaign:campaignLab,diagnose:diagnoseLab}[labTab])()}</div>${footer()}`;}
function queries(){const b=biz();return [{term:b.customer[1],clicks:22,cost:22*b.cpc,out:2,answer:'keep',why:P('Service/product aur area relevant hain. Performance ko mature sample se evaluate karo.','The service/product and area fit. Evaluate performance with a mature sample.')},{term:b.bad[1],clicks:12,cost:12*b.cpc,out:0,answer:'block',why:P('Ye business ki offer se alag intent hai. Suitable negative ki scope aur match type choose karo.','This is a different intent from the offer. Choose a suitable negative scope and match type.')},{term:state.business==='shop'?'best running shoes for beginners':state.business==='b2b'?'small business bookkeeping prices':'AC service charges Lahore',clicks:18,cost:18*b.cpc,out:1,answer:'keep',why:P('Commercial research relevant ho sakti hai. Qualified results aur offer dekho.','Commercial research can be relevant. Check qualified outcomes and the offer.')},{term:state.business==='shop'?'free running shoes giveaway':state.business==='b2b'?'free accounting course':'free AC repair course',clicks:15,cost:15*b.cpc,out:0,answer:'block',why:P('Hum giveaway/course nahi bech rahay. Is case mein intent mismatch hai.','We do not offer a giveaway/course. This case has an intent mismatch.')},{term:state.business==='shop'?'cheap running shoes':state.business==='b2b'?'cheap accountant':'cheap AC repair',clicks:3,cost:3*b.cpc,out:0,answer:'investigate',why:P('Cheap ko universally block nahi karte. Pricing fit aur sample insufficient hai; investigate karo.','“Cheap” is not a universal exclusion. Check pricing fit; this sample is small.')},{term:state.business==='shop'?'running shoes size guide':state.business==='b2b'?'bookkeeping software comparison':'AC not cooling what to do',clicks:4,cost:4*b.cpc,out:0,answer:'investigate',why:P('Research intent hai. Landing page, funnel role aur budget ke hisaab se decision lo.','This is research intent. Decide using the page, funnel role and budget.')}];}
function keywordLab(){return `<div class="card"><div class="simulation-label">SIMULATED DATA · ${esc(t(biz().name))}</div><h2 style="margin-top:10px">${U('Ye search rakhni hai ya block?','Keep, block or investigate?')}</h2><p>${U('Har row ka decision select karo. Sab zero-conversion terms automatically waste nahi hotay.','Choose a decision for each row. Zero conversions do not automatically mean waste.')}</p><div class="table-wrap"><table><thead><tr><th>SEARCH TERM</th><th>CLICKS</th><th>SPEND</th><th>${U('OUTCOMES','OUTCOMES')}</th><th>${U('TUMHARA DECISION','YOUR DECISION')}</th></tr></thead><tbody>${queries().map((q,i)=>`<tr><td>${esc(q.term)}</td><td>${q.clicks}</td><td>${money(q.cost)}</td><td>${q.out}</td><td><select data-query="${i}" aria-label="Decision for ${esc(q.term)}"><option value="">${U('Choose karo','Choose')}</option><option value="keep">Keep</option><option value="block">Block</option><option value="investigate">Investigate</option></select></td></tr>`).join('')}</tbody></table></div><div class="action-row"><button class="btn" id="check-queries">${U('Mere decisions check karo','Check my decisions')}</button></div><div id="query-feedback" aria-live="polite"></div></div>`;}
function draft(){return state.drafts[state.business]||{};}
function adLab(){const b=biz(),d=draft();return `<div class="cards"><section class="card"><div class="eyebrow">01 · WRITE</div><h2>${U('Apna pehla Search ad','Your first Search ad')}</h2><p>${U('Simple practice: 3 headlines aur 2 descriptions. Ye full Google editor nahi.','Simple practice: three headlines and two descriptions. This is not the full Google editor.')}</p>${[0,1,2].map((n)=>`<label class="field">Headline ${n+1}<input data-ad="h${n}" maxlength="30" value="${esc(d['h'+n]??[b.offer[1],b.benefit[1],'Explore Our Services'][n])}"><small id="count-h${n}"></small></label>`).join('')}${[0,1].map(n=>`<label class="field">Description ${n+1}<textarea data-ad="d${n}" maxlength="90">${esc(d['d'+n]??[b.desc[1],'Visit our website to check details and request the next step.'][n])}</textarea><small id="count-d${n}"></small></label>`).join('')}<button class="btn" id="save-ad">${U('Ad draft save karo','Save ad draft')}</button></section><section><div class="card"><div class="eyebrow">02 · PREVIEW</div><div class="simulation-label">ILLUSTRATION · NOT A GOOGLE SCREENSHOT</div><div class="campaign-preview" style="margin-top:18px"><small>Sponsored · ${esc(t(b.name))}</small><p>${esc(b.domain)}</p><h3 id="ad-headline"></h3><p id="ad-description"></p></div><p>${U('Display combinations vary kar saktay hain. Preview performance ya approval predict nahi karta.','Display combinations vary. This preview does not predict performance or approval.')}</p><div id="ad-feedback" aria-live="polite"></div></div><div class="example"><b>${U('Ek chhota rule','One small rule')}</b><p>${U('Jo promise ad mein karo, landing page par bhi wohi hona chahiye. Fake discount ya unverified guarantee add mat karo.','The landing page must support the ad’s promise. Avoid fake discounts and unverified guarantees.')}</p></div></section></div>`;}
function campaignLab(){return expandedCampaignLab();}
function checklist(){return `<div class="checklist">${LAUNCH_CHECKS.map((x,i)=>`<label><input type="checkbox" data-check="${i}" ${checksForBusiness().includes(i)?'checked':''}><span>${esc(t(x))}</span></label>`).join('')}</div>`;}
const CASES=[{title:P('20 leads, lekin asal mein 10','20 leads, but only 10 in reality'),body:P('CRM mein 10 unique forms hain. Ads tag aur GA4 import dono same forms primary count kar rahay hain.','The CRM has ten unique forms. Both the Ads tag and a GA4 import count the same forms as primary.'),opts:[P('Budget double karo','Double the budget'),P('Duplicate counting investigate aur fix karo','Investigate and fix duplicate counting'),P('Leads ko 20 hi report karo','Keep reporting 20 leads')],answer:1,why:P('Same business outcome ki duplicate primary measurement decision ko mislead karti hai.','Duplicate primary measurement of the same outcome misleads decisions.')},{title:P('Campaign bilkul serve nahi ho rahi','The campaign is not serving'),body:P('AC repair campaign approved hai, lekin campaign-level negative “repair” add hai.','The AC repair campaign is approved, but “repair” is a campaign-level negative.'),opts:[P('Negative conflict resolve karo','Resolve the negative conflict'),P('CPC 10× karo','Increase CPC tenfold'),P('Nayi unrelated website banao','Build an unrelated website')],answer:0,why:P('Eligibility conflict ko bid se solve nahi kar saktay.','A bid increase cannot resolve an eligibility conflict.')},{title:P('3× ROAS, phir bhi loss','3× ROAS, still a loss'),body:P('Rs 30,000 revenue, Rs 10,000 ad spend aur 25% contribution margin before ads.','Rs 30,000 revenue, Rs 10,000 ad spend and a 25% contribution margin before ads.'),opts:[P('Rs 20,000 profit','Rs 20,000 profit'),P('Rs 2,500 contribution loss after ads','Rs 2,500 contribution loss after ads'),P('Rs 30,000 profit','Rs 30,000 profit')],answer:1,why:P('30,000 × 0.25 − 10,000 = −2,500; fixed overhead abhi include nahi.','30,000 × 0.25 − 10,000 = −2,500, before fixed overhead.')},{title:P('Kal ke clicks ko judge karna','Judging yesterday’s clicks'),body:P('B2B mein average sale delay 21 days hai. Kal 15 relevant clicks aur zero closed sales aayi.','The B2B sales cycle averages 21 days. Yesterday produced 15 relevant clicks and no closed sales.'),opts:[P('Saari relevant keywords block karo','Block all relevant keywords'),P('Tracking/quality check karo aur mature data ka wait karo','Check tracking/quality and wait for mature outcomes'),P('Sales delay ignore karo','Ignore sales delay')],answer:1,why:P('Small sample aur sales delay ko ignore karne se premature decisions hotay hain.','Ignoring sample size and sales delay causes premature decisions.')}];
function diagnoseLab(){return `<div class="cards">${CASES.map((c,i)=>`<section class="card"><div class="eyebrow">CASE ${i+1} · ${state.diagnosed.includes(i)?'SOLVED':'YOUR TURN'}</div><h3>${esc(t(c.title))}</h3><p>${esc(t(c.body))}</p><div class="quiz-options">${c.opts.map((o,j)=>`<button class="option" data-case="${i}" data-caseanswer="${j}">${esc(t(o))}</button>`).join('')}</div><div id="case-feedback-${i}" aria-live="polite"></div></section>`).join('')}</div>`;}
function calculatorPage(){const b=biz();return `${heading('MAKE THE NUMBERS MAKE SENSE',U('Numbers badlo. Asar dekho.','Change the numbers. See the impact.'),U('PKR examples. Formulas kisi bhi currency mein same hain.','Examples use PKR. The formulas work in any currency.'))}<div class="tabs">${[['forecast',P('Forecast aur profit','Forecast & contribution')],['metrics',P('Actual metrics','Actual metrics')],['budget',P('Budget planning','Budget planning')]].map(([k,n])=>`<button data-calctab="${k}" class="${k===calcTab?'active':''}">${t(n)}</button>`).join('')}</div><div class="cards"><section class="card"><h3>${U('Apne assumptions dalo','Enter your assumptions')}</h3><p>${U('Sample numbers market benchmarks nahi hain. Apne data se replace karo.','Sample numbers are not market benchmarks. Replace them with your data.')}</p><form id="calc-form"><div class="form-grid">${(calcTab==='forecast'?[['spend','Ad budget (Rs)',10000,1,1000000000],['cpc','Average CPC (Rs)',b.cpc,.01,1000000],['cvr','Click → lead / order CVR (%)',b.cvr,0,100],['close','Lead → customer close rate (%)',b.close,0,100],['aov','Revenue per customer / order (Rs)',b.aov,0,1000000000],['margin','Contribution margin before ads (%)',b.margin,0,100]]:calcTab==='metrics'?[['impressions','Impressions',2000,0,1000000000],['clicks','Clicks',100,0,1000000000],['spend','Spend (Rs)',5000,0,1000000000],['conversions','Conversions',5,0,1000000000],['revenue','Attributed revenue (Rs)',16000,0,1000000000],['margin','Contribution margin before ads (%)',40,0,100]]:[['monthly','Monthly ad budget (Rs)',30400,1,1000000000],['cpc','Expected CPC (Rs)',b.cpc,.01,1000000]]).map(([id,label,value,min,max])=>`<label class="field">${label}<input type="number" id="calc-${id}" value="${value}" min="${min}" max="${max}" step="any" required></label>`).join('')}</div></form><div class="note">${U('Contribution margin mein relevant variable costs include karo. Output fixed overhead, tax treatment aur future repeat purchases ko automatically include nahi karta.','Include relevant variable costs in contribution margin. Outputs do not automatically include fixed overhead, tax treatment or future repeat purchases.')}</div></section><section class="card"><div class="eyebrow">YOUR NUMBERS, EXPLAINED</div><div id="calc-results" aria-live="polite"></div></section><div class="card wide"><h3>${U('Formula samjho','Understand the formulas')}</h3><div class="formula" id="calc-formula" style="margin-top:15px"></div></div></div>${footer()}`;}
function metric(label,value,explain){return `<div class="metric"><span>${label}</span><b>${value}</b><small>${explain}</small></div>`;}
function calcResults(){const inputs=$$('#calc-form input');if(!inputs.length)return;const valid=inputs.every(i=>i.value.trim()!==''&&i.checkValidity()&&Number.isFinite(+i.value));if(!valid){$('#calc-results').innerHTML=`<div class="feedback error">${U('Valid numbers dalo. Rates 0–100% aur CPC zero se zyada ho.','Enter valid numbers. Rates must be 0–100% and CPC must be greater than zero.')}</div>`;return;}const v=Object.fromEntries(inputs.map(i=>[i.id.slice(5),+i.value]));let html='',formula='';if(calcTab==='forecast'){const clicks=v.spend/v.cpc,leads=clicks*v.cvr/100,customers=leads*v.close/100,revenue=customers*v.aov,contrib=revenue*v.margin/100-v.spend,beCPL=v.aov*v.margin/100*v.close/100;html=`<div class="metrics">${metric('Expected clicks',num(clicks),'Budget ÷ CPC')}${metric('Expected leads / orders',num(leads),'Clicks × CVR')}${metric('Expected customers',num(customers),'Leads × close rate')}${metric('Estimated revenue',money(revenue),'Customers × revenue each')}${metric('Contribution after ads',money(contrib),'Before fixed overhead')}${metric('Break-even CPL / order CPA',money(beCPL),'Contribution × close rate')}${metric('Expected acquisition cost',customers?money(v.spend/customers):'—','Spend ÷ customers')}${metric('Break-even max CPC',money(beCPL*v.cvr/100),'Break-even CPL × CVR')}</div><p style="font-size:12px">${U('Ye assumptions ka model hai, actual Google forecast ya guarantee nahi.','This is an assumption-based model, not an actual Google forecast or guarantee.')}</p>`;formula='Clicks = budget / CPC\nLeads = clicks × (CVR / 100)\nCustomers = leads × (close rate / 100)\nContribution after ads = customers × revenue/customer × margin − budget\nBreak-even CPL = revenue/customer × margin × close rate\nBreak-even max CPC = break-even CPL × CVR';}else if(calcTab==='metrics'){if(v.clicks>v.impressions){$('#calc-results').innerHTML=`<div class="feedback error">${U('Is simple Search example mein clicks impressions se zyada nahi ho saktay.','In this simple Search example, clicks cannot exceed impressions.')}</div>`;return;}const ratio=(a,b)=>b?a/b:NaN;html=`<div class="metrics">${metric('CTR',num(ratio(v.clicks,v.impressions)*100)+'%','Clicks ÷ impressions')}${metric('Average CPC',money(ratio(v.spend,v.clicks)),'Spend ÷ clicks')}${metric('CVR · click-based',num(ratio(v.conversions,v.clicks)*100)+'%','Conversions ÷ clicks')}${metric('CPA',money(ratio(v.spend,v.conversions)),'Spend ÷ conversions')}${metric('Revenue ROAS',num(ratio(v.revenue,v.spend),2)+'×','Revenue ÷ spend')}${metric('Contribution after ads',money(v.revenue*v.margin/100-v.spend),'Before fixed overhead')}${metric('Break-even ROAS',v.margin?num(100/v.margin,2)+'×':'—','1 ÷ margin fraction')}</div><p style="font-size:12px">${U('“—” ka matlab undefined hai, zero cost nahi. Multiple conversion actions ki wajah se CVR 100% se zyada bhi ho sakta hai.','“—” means undefined, not zero cost. CVR can exceed 100% when multiple conversion actions are counted.')}</p>`;formula='CTR (%) = clicks / impressions × 100\nCPC = spend / clicks\nCVR (%) = conversions / clicks × 100 (this Search example)\nCPA = spend / conversions\nROAS = revenue / spend\nBreak-even revenue ROAS = 1 / contribution margin fraction';}else{const daily=v.monthly/30.4;html=`<div class="metrics">${metric('Average daily budget',money(daily),'Monthly budget ÷ 30.4')}${metric('Illustrative daily upper spend',money(daily*2),'Most campaigns: up to 2×')}${metric('Illustrative monthly limit',money(v.monthly),'Unchanged budget, full month')}${metric('Estimated monthly clicks',num(v.monthly/v.cpc),'Budget ÷ expected CPC')}</div><p style="font-size:12px">${U('Budget changes, campaign exceptions aur taxes/fees se billing differ kar sakti hai.','Budget changes, campaign exceptions and taxes/fees can affect billing.')}</p>${sourceLinks(['budget'])}`;formula='Average daily budget = full-month budget / 30.4\nIllustrative daily spending limit = average daily budget × 2\nIllustrative monthly limit = average daily budget × 30.4\nAssumes most standard campaigns and an unchanged full-month budget.';}$('#calc-results').innerHTML=html;$('#calc-formula').textContent=formula;}
function mediaPage(){return `${heading('SEE IT IN CONTEXT',U('Official visuals aur walkthroughs','Official visuals and walkthroughs'),U('Google ki original media, source ke saath. Teaching simulations alag labelled hain.','Original Google media with attribution. Teaching simulations are labelled separately.'))}<div class="note" style="margin-bottom:22px">${U('9 original interface crops ab available hain; complete workflow screenshots aur Roman Urdu recordings baqi hain. Neechay Google ki official animation aur English videos hain; video ki UI publication date ke mutabiq ho sakti hai. Captions player par available hon to use karein.','Nine original interface crops are available; full workflow screenshots and Roman Urdu recordings remain. Below are official Google animation and English videos; video UI may reflect its publication date. Use player captions where available.')}</div><div class="action-row" style="margin-bottom:22px"><button class="btn" data-go="screens">${U("Real screenshots walkthrough kholo","Open the real screenshots walkthrough")} →</button></div><div class="cards"><article class="resource"><a href="assets/ai-max-official.gif" target="_blank" rel="noopener"><img src="assets/ai-max-official.gif" alt="Official Google AI Max interface animation" loading="lazy"></a><div class="body"><span class="tag">ORIGINAL GOOGLE ANIMATION</span><h3 style="margin-top:12px">AI Max · interface walkthrough</h3><p>${U('Google Help se original animation. Open karke zoom kar saktay ho. Har account ka layout same honay ki guarantee nahi.','Original animation from Google Help. Open to zoom. Account layouts can vary.')}</p>${sourceLinks(['ai'])}<small>Source checked: 20 Oct 2026 · © Google</small></div></article>${OFFICIAL_VIDEOS.map(officialVideoCard).join('')}</div>${footer()}`;}
function referencePage(){return `${heading('YOUR SEARCH ADS COMPANION',U('Jab bhoolo, yahan dhoondo.','Forgot something? Find it here.'),U('Terms, formulas, official guides aur coverage checklist.','Terms, formulas, official guides and the coverage checklist.'))}<input class="search-input" id="reference-search" type="search" placeholder="${U('Keyword, CPA, ROAS, tracking… dhoondo','Find keyword, CPA, ROAS, tracking…')}" aria-label="Search glossary and lessons"><div class="tabs"><button class="active" data-reftab="glossary">${U('Simple dictionary','Simple dictionary')}</button><button data-reftab="sources">${U('Official sources','Official sources')}</button><button data-reftab="coverage">${U('Coverage aur pending work','Coverage & remaining work')}</button></div><div id="reference-content">${glossary('')}</div>${footer()}`;}
function glossary(q){const needle=q.toLowerCase(),items=GLOSSARY.filter(x=>x.join(' ').toLowerCase().includes(needle)),lessons=needle?LESSONS.filter(l=>(l.title.join(' ')+l.why.join(' ')).toLowerCase().includes(needle)):[];return `${lessons.length?`<div class="card" style="margin-bottom:20px"><h3>${U('Related lessons','Related lessons')}</h3>${lessons.map(l=>`<button class="lesson-link" data-go="lesson/${l.id}">↗ ${esc(t(l.title))}</button>`).join('')}</div>`:''}<div class="cards">${items.map(x=>`<article class="card"><h3>${esc(x[0])}</h3><p>${esc(x[state.lang?2:1])}</p></article>`).join('')}</div>${!items.length&&!lessons.length?`<div class="empty">${U('Koi result nahi. Doosra term try karo.','No results. Try a different term.')}</div>`:''}`;}
function coverage(){return `<div class="card"><h2>${U('Transparent coverage','Transparent coverage')}</h2><p>${U('Ye pehli working edition hai: 42 concise lessons, full professional implementation course abhi nahi. Har listed topic ka intro aur practice path hai; deeper material ko expand karna baqi hai.','This is the first working edition: 42 concise lessons, not yet a full professional implementation course. Listed topics have introductory coverage and a practice path; deeper material needs expansion.')}</p>${CHAPTERS.map((c,i)=>`<div class="coverage-item"><b>${esc(c[state.lang?0:1])}</b><span>3 lessons · introductory</span></div>`).join('')}<h3 style="margin-top:25px">${U('Abhi baqi hai','Remaining work')}</h3><ol class="steps"><li>${U('Current demo account ke har important workflow ki screenshots aur annotated walkthroughs.','Current demo-account screenshots and annotated walkthroughs for each important workflow.')}</li><li>${U('Roman Urdu short recorded videos aur reviewed transcripts.','Short Roman Urdu recordings and reviewed transcripts.')}</li><li>${U('Real, permission-based campaign case studies; abhi saaray business numbers fictional examples hain.','Real campaign case studies used with permission; all current business numbers are fictional examples.')}</li><li>${U('Tracking workbook available hai; live account verification, advanced consent implementation aur experiments ki exercises baqi hain.','The tracking workbook is available; live account verification, advanced consent implementation and experiment exercises remain.')}</li><li>${U('Expert review aur real beginner usability testing; quiz score professional certification nahi.','Expert review and real beginner usability testing; quiz scores are not professional certification.')}</li><li>${U('Baaki campaign modules: Display, Shopping, Video, App, Demand Gen aur Performance Max.','Other campaign modules: Display, Shopping, Video, App, Demand Gen and Performance Max.')}</li></ol></div>`;}
function progressPage(){const correct=LESSONS.filter(l=>state.answers[l.id]===l.answer).length;return `${heading('EVERY SMALL STEP COUNTS',U('Tumhari progress','Your progress'),U('Progress is browser/device mein save hoti hai. Backup download kar saktay ho.','Progress is saved in this browser/device. You can download a backup.'))}<div class="stats"><div class="stat"><span class="stat-icon">${icon('book')}</span><div><strong>${state.done.length}/${LESSONS.length}</strong><p>Lessons completed</p></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${correct}/${LESSONS.length}</strong><p>Knowledge checks correct</p></div></div><div class="stat"><span class="stat-icon">${icon('tool')}</span><div><strong>${state.diagnosed.length}/${CASES.length}</strong><p>Diagnosis cases solved</p></div></div></div><div class="cards"><div class="card"><h3>${U('Chapter progress','Chapter progress')}</h3>${CHAPTERS.map((c,i)=>{const ls=LESSONS.filter(l=>l.c===i),d=ls.filter(l=>state.done.includes(l.id)).length;return `<div style="margin-top:18px"><div class="section-heading" style="margin-bottom:8px;font-size:12px"><span>${esc(c[state.lang?0:1])}</span><span>${d}/${ls.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${d/ls.length*100}%"></div></div></div>`;}).join('')}</div><aside><div class="card"><h3>${U('Practice readiness','Practice readiness')}</h3><p>${U('Self-check aur simulated results. Live account expertise ka certification nahi.','Self-checks and simulated results. This is not certification of live account expertise.')}</p><div class="coverage-item"><b>Search-term lab</b><span>${Math.max(0,...Object.values(state.keywordScores))}/6 best</span></div><div class="coverage-item"><b>Ad drafts</b><span>${Object.values(state.drafts).filter(d=>d.adSaved).length}/3</span></div><div class="coverage-item"><b>Guided decisions</b><span>${missionStepsSolved()}/45 across 3 businesses</span></div><div class="coverage-item"><b>Calculation drills</b><span>${Object.keys(state.maths).length}/36 across 3 businesses</span></div><div class="coverage-item"><b>Worked case checks</b><span>${BUSINESSES.reduce((sum,b)=>sum+caseSolvedForBusiness(b.id),0)}/18</span></div><div class="coverage-item"><b>Advanced search-term decisions · ${esc(t(biz().name))}</b><span>${studioQueryScore()}/8</span></div><div class="coverage-item"><b>Optimization decisions · ${esc(t(biz().name))}</b><span>${optimizationSolved()}/6</span></div><div class="coverage-item"><b>Measurement fixtures</b><span>${state.clinic.traces.length}/3</span></div><div class="coverage-item"><b>Consent decisions</b><span>${CONSENT_CASES.filter(c=>state.clinic.consent.answers[c.id]===c.answer).length}/6</span></div><div class="coverage-item"><b>Fault diagnoses</b><span>${clinicSolved()}/8</span></div><div class="coverage-item"><b>Setup walkthrough · ${esc(t(biz().name))}</b><span>${journeySolved()}/14</span></div><div class="coverage-item"><b>Workbook self-checks</b><span>${Object.values(state.guideChecks).reduce((sum,a)=>sum+a.length,0)}/69 across 3 businesses</span></div><div class="coverage-item"><b>Launch self-checks · ${esc(t(biz().name))}</b><span>${checksForBusiness().length}/${LAUNCH_CHECKS.length}</span></div><div class="action-row"><button class="btn" data-go="lesson/${nextLesson().id}">${U('Continue karo','Continue learning')} →</button></div></div><div class="card" style="margin-top:18px"><h3>${U('Apni learning sambhalo','Keep your learning')}</h3><p>${U('Backup mein progress aur fictional campaign drafts hain. Sensitive client data mat add karo.','Backups contain progress and fictional campaign drafts. Do not add sensitive client data.')}</p><div class="action-row"><button class="btn light" id="export-progress">${U('Backup download','Download backup')}</button><label class="btn light" style="cursor:pointer">${U('Backup restore','Restore backup')}<input type="file" id="import-progress" accept="application/json" class="hidden"></label></div><button class="text-btn" id="reset-progress" style="margin-top:20px;color:#97674d">${U('Progress reset…','Reset progress…')}</button><div id="reset-confirm"></div></div></aside></div>${footer()}`;}
function bind(){bindNavigation();$$('[data-workshop-open]').forEach(b=>b.onclick=()=>{const target=b.dataset.workshopOpen;workshopTab=['math','case'].includes(target)?target:'missions';if(!['math','case'].includes(target))missionId=target;go('workshop');});$('#language').onchange=e=>{state.lang=+e.target.value;save();render();};$$('[data-business]').forEach(b=>b.onclick=()=>{state.business=b.dataset.business;save();render();});$$('[data-answer]').forEach(b=>b.onclick=()=>{const y=window.scrollY;state.answers[+b.dataset.lesson]=+b.dataset.answer;save();render();window.scrollTo(0,y);});const complete=$('#complete-lesson');if(complete)complete.onclick=()=>{const id=+complete.dataset.id;if(state.answers[id]!==LESSONS[id].answer)return;if(!state.done.includes(id))state.done.push(id);save();go(id<LESSONS.length-1?'lesson/'+(id+1):'progress');};$$('[data-lab]').forEach(b=>b.onclick=()=>{const k=b.dataset.lab;if(k==='calculator')go('calculators');else if(k==='media')go('media');else if(k==='checklist'){labTab='campaign';go('lab');}else if(k==='types'){$('#types-gallery')?.scrollIntoView({behavior:'smooth',block:'start'});}else{labTab=k;go('lab');}});$$('[data-calctab]').forEach(b=>b.onclick=()=>{calcTab=b.dataset.calctab;render();});const form=$('#calc-form');if(form){form.oninput=calcResults;form.onsubmit=e=>e.preventDefault();}const ex=$('#export-progress');if(ex)ex.onclick=()=>download('ads-asaan-progress.json',{schema:1,exportedAt:new Date().toISOString(),state});const im=$('#import-progress');if(im)im.onchange=restore;const reset=$('#reset-progress');if(reset)reset.onclick=()=>{$('#reset-confirm').innerHTML=`<div class="note" style="margin-top:14px">${U('Is browser ki progress aur drafts delete ho jayenge.','Progress and drafts in this browser will be deleted.')}<div class="action-row"><button class="btn" id="confirm-reset">${U('Haan, reset karo','Confirm reset')}</button><button class="btn light" id="cancel-reset">${U('Cancel','Cancel')}</button></div></div>`;$('#cancel-reset').onclick=()=>$('#reset-confirm').innerHTML='';$('#confirm-reset').onclick=()=>{state=structuredClone(initial);save();render();toast(U('Progress reset ho gayi','Progress reset'));};};}
function bindNavigation(){ $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
function download(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function restore(e){try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('File too large');const x=JSON.parse(await f.text());if(x.schema!==1||!x.state||!Array.isArray(x.state.done)||![0,1].includes(x.state.lang)||!BUSINESSES.some(b=>b.id===x.state.business))throw Error('Invalid backup');const s=x.state;state={...structuredClone(initial),lang:s.lang,business:s.business,done:[...new Set(s.done.filter(i=>Number.isInteger(i)&&i>=0&&i<LESSONS.length))],answers:Object.fromEntries(Object.entries(s.answers||{}).filter(([k,v])=>LESSONS[k]&&Number.isInteger(v)&&v>=0&&v<LESSONS[k].options.length)),checks:[...new Set((s.checks||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<LAUNCH_CHECKS.length))],diagnosed:[...new Set((s.diagnosed||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<CASES.length))],keywordScores:Object.fromEntries(Object.entries(s.keywordScores||{}).filter(([k,v])=>BUSINESSES.some(b=>b.id===k)&&Number.isInteger(v)&&v>=0&&v<=6)),drafts:{}};for(const b of BUSINESSES){const d=s.drafts?.[b.id];if(d&&typeof d==='object'){state.drafts[b.id]={};for(const [k,v]of Object.entries(d))if(['h0','h1','h2','d0','d1','name','goal','location','budget','bid','keywords','negatives','url','adSaved','validated',...CAMPAIGN_FIELDS].includes(k)&&['string','number','boolean'].includes(typeof v))state.drafts[b.id][k]=typeof v==='string'?v.slice(0,10000):v;}}state.missions=cleanMissions(s.missions);state.maths=cleanMaths(s.maths);state.businessChecks=s.businessChecks;state.guideChecks=s.guideChecks;migrateBusinessChecks();state.casePlans=cleanCasePlans(s.casePlans);state.journey=cleanJourney(s.journey);state.clinic=cleanClinic(s.clinic);state.optimization=cleanOptimization(s.optimization);state.studio=cleanStudio(s.studio);state.destination=cleanDestination(s.destination);save();render();toast(U('Backup restore ho gaya','Backup restored'));}catch{toast(U('Valid Ads Asaan backup choose karo','Choose a valid Ads Asaan backup'));}}
function bindLab(){const sel=$('#business-select');if(sel)sel.onchange=e=>{state.business=e.target.value;save();render();};$$('[data-labtab]').forEach(b=>b.onclick=()=>{labTab=b.dataset.labtab;render();});$$('[data-check]').forEach(el=>el.onchange=()=>{const i=+el.dataset.check;state.businessChecks[state.business]=checksForBusiness().filter(x=>x!==i);if(el.checked)checksForBusiness().push(i);save();});if(labTab==='keywords')$('#check-queries').onclick=()=>{const selections=$$('[data-query]');if(selections.some(s=>!s.value)){toast(U('Pehle har row ka decision choose karo','Choose a decision for every row first'));return;}let score=0;const feedback=queries().map((q,i)=>{const ok=selections[i].value===q.answer;if(ok)score++;return `<div class="feedback ${ok?'':'error'}" style="margin-top:10px"><b>${ok?'✓':'↻'} ${esc(q.term)}</b><br>${U('Suggested decision','Suggested decision')}: ${q.answer}. ${esc(t(q.why))}</div>`;}).join('');state.keywordScores[state.business]=Math.max(score,state.keywordScores[state.business]||0);save();$('#query-feedback').innerHTML=`<h3 style="margin-top:22px">${score}/6 ${U('decisions match huay','decisions matched')}</h3>${feedback}`;};if(labTab==='ad'){const update=()=>{const vals=Object.fromEntries($$('[data-ad]').map(i=>[i.dataset.ad,i.value]));$('#ad-headline').textContent=[vals.h0,vals.h1,vals.h2].filter(Boolean).join(' | ');$('#ad-description').textContent=[vals.d0,vals.d1].filter(Boolean).join(' ');$$('[data-ad]').forEach(i=>$('#count-'+i.dataset.ad).textContent=`${[...i.value].length}/${i.dataset.ad[0]==='h'?30:90} characters`);};$$('[data-ad]').forEach(i=>i.oninput=update);update();$('#save-ad').onclick=()=>{const vals=Object.fromEntries($$('[data-ad]').map(i=>[i.dataset.ad,i.value.trim()]));if(Object.values(vals).some(v=>!v)){toast(U('3 headlines aur 2 descriptions complete karo','Complete all three headlines and both descriptions'));return;}state.drafts[state.business]={...draft(),...vals,adSaved:true};save();$('#ad-feedback').innerHTML=`<div class="feedback">✓ ${U('Draft save ho gaya. Relevance aur claims khud review karo; ye Google approval ya Ad Strength score nahi.','Draft saved. Review relevance and claims yourself; this is not Google approval or an Ad Strength score.')}</div>`;};}if(labTab==='campaign'){$('#validate-campaign').onclick=validateCampaign;$('#export-campaign').onclick=()=>{captureCampaign();download('ads-asaan-'+state.business+'-draft.json',{simulation:true,business:biz().name[1],draft:draft(),selfChecks:checksForBusiness().map(i=>LAUNCH_CHECKS[i][1]),exportedAt:new Date().toISOString()});};$('#simulate-launch').onclick=()=>{const ok=validateCampaign();$('#launch-feedback').innerHTML=`<div class="feedback ${ok&&checksForBusiness().length===LAUNCH_CHECKS.length?'':'error'}" style="margin-top:15px">${ok&&checksForBusiness().length===LAUNCH_CHECKS.length?U('Practice plan checks complete. Real launch se pehle actual tracking, policies aur account settings independently verify karo.','Practice plan checks complete. Independently verify real tracking, policies and account settings before a real launch.'):U('Draft ki warnings aur incomplete self-checks resolve karo.','Resolve draft warnings and incomplete self-checks.')}</div>`;};}if(labTab==='diagnose')$$('[data-case]').forEach(b=>b.onclick=()=>{const id=+b.dataset.case,c=CASES[id],ok=+b.dataset.caseanswer===c.answer;if(ok&&!state.diagnosed.includes(id))state.diagnosed.push(id);save();$('#case-feedback-'+id).innerHTML=`<div class="feedback ${ok?'':'error'}"><b>${ok?U('Sahi diagnosis.','Correct diagnosis.'):U('Dobara try karo.','Try again.')}</b> ${esc(t(c.why))}</div>`;});}
function captureCampaign(){return readCampaignDraft();}
function validateCampaign(){return expandedValidateCampaign();}
function bindReference(){const search=$('#reference-search');search.oninput=()=>{$$('#reference-content').forEach(e=>e.innerHTML=glossary(search.value));$$('[data-reftab]').forEach(b=>b.classList.toggle('active',b.dataset.reftab==='glossary'));bindNavigation();};$$('[data-reftab]').forEach(b=>b.onclick=()=>{$$('[data-reftab]').forEach(x=>x.classList.toggle('active',x===b));$('#reference-content').innerHTML=b.dataset.reftab==='glossary'?glossary(search.value):b.dataset.reftab==='coverage'?coverage():`<div class="card"><h3>${U('Primary Google documentation','Primary Google documentation')}</h3><p>${U('Checked 20 Oct 2026. Docs aur features change ho saktay hain; account-level availability verify karo.','Checked 20 Oct 2026. Documentation and features can change; verify account availability.')}</p>${sourceLinks(Object.keys(SOURCES))}</div>`;bindNavigation();});}
function bindMedia(){$$('[data-video]').forEach(b=>b.onclick=()=>{const id=b.dataset.video;const holder=document.querySelector(`[data-video-holder="${id}"]`);holder.className='';holder.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1" title="Official Google Ads tutorial" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;});}
window.addEventListener('hashchange',render);render();
